/// Returns the message definition sent as `code^event` (`MSH-9.1` and
/// `MSH-9.2`), for example `ORU` and `R01`.
#[must_use]
pub fn find(code: &str, event: &str) -> Option<&'static crate::model::Message> {
    match MESSAGES.binary_search_by(|entry| (entry.code, entry.event).cmp(&(code, event))) {
        Ok(index) => MESSAGES.get(index).copied(),
        Err(_) => None,
    }
}

