/// Returns the legacy entries sent as `code^event` (`MSH-9.1` and
/// `MSH-9.2`), for example `ORM` and `O01`, one per version in version order.
#[must_use]
pub fn legacy(code: &str, event: &str) -> &'static [crate::model::LegacyMessage] {
    let start = LEGACY.partition_point(|entry| (entry.code, entry.event) < (code, event));
    let end = LEGACY.partition_point(|entry| (entry.code, entry.event) <= (code, event));
    LEGACY.get(start..end).unwrap_or(&[])
}

/// Returns the legacy entry sent as `code^event` in the tables of `version`
/// (`MSH-12`), for example `ORM`, `O01` and `2.5.1`.
#[must_use]
pub fn find_legacy(
    code: &str,
    event: &str,
    version: &str,
) -> Option<&'static crate::model::LegacyMessage> {
    legacy(code, event)
        .iter()
        .find(|entry| entry.version == version)
}
